import logging

import monasca_setup.agent_config
import monasca_setup.detection

log = logging.getLogger(__name__)


class HttpCheck(monasca_setup.detection.ArgsPlugin):
    """ Setup an http_check according to the passed in args.
        Despite being a detection plugin this plugin does no detection and will be a noop without arguments.
        Expects space seperated arguments, the required argument is url. Optional parameters include:
        disable_ssl_validation and match_pattern.
    """

    def _detect(self):
        """Run detection, set self.available True if the service is detected.
        """
        self.available = self._check_required_args(['url'])

    def build_config(self):
        """Build the config as a Plugins object and return.
        """
        config = monasca_setup.agent_config.Plugins()
        log.info("\tEnabling the http_check plugin for {url}".format(**self.args))

        config['http_check'] = {
            'init_config': self._build_init_config(),
            'instances': [self._build_instance()]
        }

        return config

    def _build_init_config(self):
        """Build the http_check init_config as a dictionary.

            Return the init_config as a dictionary.
        """
        init_config = {}

        if hasattr(self.args, 'use_keystone'):
            init_config['use_keystone'] = self.args.use_keystone

        return init_config if init_config else None

    def _build_instance(self):
        """Build the http_check instance as a dictionary.

            Return the instance as a dictionary.
        """
        instance = {}

        # The url is required, the rest are optional
        if hasattr(self.args, 'url'):
            instance['url'] = self.args.url

        if hasattr(self.args, 'timeout'):
            instance['timeout'] = self.args.timeout

        if hasattr(self.args, 'username'):
            instance['username'] = self.args.username

        if hasattr(self.args, 'password'):
            instance['password'] = self.args.password

        if hasattr(self.args, 'match_pattern'):
            instance['match_pattern'] = self.args.match_pattern

